<div class="metric-grid"><article><span>Просмотры страниц</span><strong><?= number_format((int)$visitSummary['views'],0,',',' ') ?></strong><small>За выбранный период</small></article><article><span>Посетители</span><strong><?= number_format((int)$visitSummary['visitors'],0,',',' ') ?></strong><small>Анонимные сессии по дням</small></article><article><span>Заявки</span><strong><?= number_format($requestCount,0,',',' ') ?></strong><small>Все обращения за период</small></article><article><span>Новые заявки</span><strong><?= (int)query("SELECT COUNT(*) FROM requests WHERE status='new'")->fetchColumn() ?></strong><small>Ожидают обработки</small></article></div>
<section class="admin-panel"><div class="panel-title"><h2>Посещения по дням</h2><span><?= e($from) ?> — <?= e($to) ?></span></div><?php if($daily): ?><?php $width=760;$height=190;$max=max(1,...array_map(fn($d)=>(int)$d['views'],$daily));$barWidth=($width-40)/count($daily); ?><svg class="stats-chart" viewBox="0 0 800 250" role="img" aria-label="Число просмотров по дням"><line x1="30" y1="205" x2="780" y2="205" stroke="#dce5ec"/><text x="4" y="20" font-size="11" fill="#5f6d81"><?= $max ?></text><text x="12" y="205" font-size="11" fill="#5f6d81">0</text><?php foreach($daily as $i=>$d):$h=(int)$d['views']/$max*$height;$x=35+$i*$barWidth; ?><rect x="<?= round($x,2) ?>" y="<?= round(205-$h,2) ?>" width="<?= max(2,round($barWidth*.7,2)) ?>" height="<?= max(1,round($h,2)) ?>" rx="4" fill="#1f4e79"><title><?= e($d['day']) ?>: <?= (int)$d['views'] ?> просмотров, <?= (int)$d['visitors'] ?> посетителей</title></rect><?php if($i===0||$i===count($daily)-1||($i%max(1,(int)ceil(count($daily)/8))===0)): ?><text x="<?= round($x,2) ?>" y="230" font-size="10" fill="#5f6d81"><?= e(date('d.m',strtotime($d['day']))) ?></text><?php endif;endforeach ?></svg><?php else: ?><p class="admin-empty">Посещения пока не зарегистрированы. Данные появятся после визитов на публичные страницы.</p><?php endif ?></section>
